/* ==========================================================================
   >>> EDIT THESE <<<
   ========================================================================== */
const SHEET_ID         = '1N-qE4v81o0uxyXxLFeCamHSkvALFQIixrES3K6-hE6c';
const SESSION_HOURS    = 24;     // a chat idle for longer than this starts fresh, and its messages are wiped from the sheet
const HISTORY_MESSAGES = 16;     // how many recent messages the assistant is shown
/* ========================================================================== */
const MESSAGE_CHARS = 1500;      // one remembered message is cut to this length

// Three ways in. The two webhooks are internal (they need the DentalFlow key)
// and take the phone number from the caller: workflow 08 passes the verified
// WhatsApp sender, never a number someone typed in a chat.
//   read  what the assistant needs before it replies: the recent chat, who
//         the patient is, and whether the team has an open request from them.
//   save  after a reply: the two new messages; and after a booking: the
//         patient's name and email, so they are not asked again next time.
//   tidy  every hour, by itself: chats idle for SESSION_HOURS have their
//         messages wiped, so old conversations do not sit in the sheet and
//         the tab stays quick to read.
const inp = $input.first().json || {};
const b = inp.body || {};
const url = String(inp.webhookUrl || '');
const mode = /memory-save/.test(url) || b.save === true ? 'save' : /memory-read/.test(url) || b.phone !== undefined ? 'read' : 'tidy';
const base = { SHEET_ID, SESSION_HOURS, HISTORY_MESSAGES, MESSAGE_CHARS };
if (mode === 'tidy') return [{ json: { ...base, mode } }];

const phone = String(b.phone || '').replace(/\D/g, '');
if (phone.length < 10) throw new Error('Missing or short "phone"');

// language: what the assistant reported when booking (en, ur, roman-ur, ar).
// script:   what the reply was written in (en = Latin letters, ar, ur). Latin
//           letters cannot tell English from Roman Urdu, so a script of "en"
//           never replaces a stored "roman-ur".
const norm = v => { const l = String(v || '').trim().toLowerCase();
  return !l ? '' : /^ar/.test(l) ? 'ar' : /roman|latn|^ru$/.test(l) ? 'roman-ur' : /^ur/.test(l) ? 'ur' : /^en/.test(l) ? 'en' : ''; };
const text = (v, n) => String(v ?? '').replace(/\r/g, '').trim().slice(0, n);
// A name or email that starts like a spreadsheet formula loses that character.
const plain = (v, n) => String(v ?? '').replace(/[\r\n\t]+/g, ' ').replace(/^[\s=+\-@]+/, '').replace(/\s{2,}/g, ' ').trim().slice(0, n);
const p = (b.profile && typeof b.profile === 'object') ? b.profile : {};
const email = plain(p.email, 120);

return [{ json: { ...base, mode, phone,
  language: norm(b.language), script: norm(b.script),
  said: text(b.said, MESSAGE_CHARS), reply: text(b.reply, MESSAGE_CHARS), note: text(b.note, 600),
  profile: { name: plain(p.name, 60), email: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email) ? email : '' },
  visit: b.visit === true } }];

/* PATIENT MEMORY: what the assistant remembers, kept in the clinic's own sheet.

   SessionState  A phone | B updated_at | C language | D history
     One row per WhatsApp number. history is the last few messages of the
     chat. Because it is in the sheet and not in n8n's memory, a chat carries
     on after n8n restarts. A chat idle for SESSION_HOURS starts fresh.
   Patients      A phone | B name | C email | D language | E first_seen | F last_seen | G visits | H notes
     One row per patient who has booked on WhatsApp. A returning patient is
     greeted by name and is not asked for it again. The first booking sets the
     name and email; later bookings (perhaps for a relative) never replace
     them. Reception can correct them in the sheet. Column H is for staff and
     is never read or written here.
   Handoffs      read only, to answer one question: does the team have anything
     open or recent for this number? Only then does workflow 08 make the full
     handoff check, so most messages skip it.

   An existing row is updated in place. A new row is APPENDED, which lets the
   sheet grow and keeps two new patients arriving together from landing on the
   same row. Everything is written as plain text (RAW), so nothing a patient
   types can become a formula.                                               */
const c   = $('Config').first().json;
const res = $input.first().json || {};
const code = Number(res.statusCode || 0);
const clean = v => String(v ?? '').trim();
const now = Date.now();

if (!(code >= 200 && code < 300)) {
  const why = clean(res.body && res.body.error && res.body.error.message) || `HTTP ${code || 'no response'}`;
  if (c.mode === 'tidy') throw new Error('The memory tabs could not be read: ' + why);
  return [{ json: { mode: c.mode, hasUpdates: false, appends: [],
    response: { ok: false, error: why, note: 'The memory tabs could not be read. Run the stage 4 sheet upgrade and check the Google Sheets credential in workflow 16.' } } }];
}

const vr = (res.body && res.body.valueRanges) || [];
const rows = i => (vr[i] && vr[i].values) || [];        // 0 SessionState 1 Patients 2 Handoffs
const fresh = r => now - (Date.parse(clean(r[1])) || 0) < c.SESSION_HOURS * 3600000;

/* ------------------------------------------------------------------- tidy */
if (c.mode === 'tidy') {
  const data = [];
  rows(0).forEach((r, i) => { if (clean(r[3]) && clean(r[3]) !== '[]' && !fresh(r) && data.length < 300) data.push({ range: `SessionState!D${i + 2}`, values: [['']] }); });
  if (!data.length) return [];
  return [{ json: { mode: 'tidy', hasUpdates: true, appends: [], SHEET_ID: c.SHEET_ID, updates: { valueInputOption: 'RAW', data }, wiped: data.length } }];
}

/* Whose row is it? Every number here was written by us from a verified
   WhatsApp sender, so two numbers are the same patient only when all their
   digits are the same. (Matching on the last digits alone would let a number
   in another country, ending the same way, read this patient's chat.)      */
const digits = v => clean(v).replace(/\D/g, '').replace(/^0+/, '');
const mine = v => { const d = digits(v); return d.length >= 10 && d === digits(c.phone); };
const find = list => { const i = list.findIndex(r => mine(r[0])); return i < 0 ? null : { r: list[i], rowNumber: i + 2 }; };

const sess = find(rows(0));
const pat  = find(rows(1));

// The remembered chat, if it is recent enough to still be the same conversation.
let history = [];
if (sess && fresh(sess.r)) {
  try { const h = JSON.parse(clean(sess.r[3]) || '[]'); if (Array.isArray(h)) history = h; } catch (e) { history = []; }
  history = history.filter(m => m && (m.r === 'p' || m.r === 'a' || m.r === 'n') && typeof m.t === 'string' && m.t)
                   .slice(-c.HISTORY_MESSAGES);
}
const LANGS = ['en', 'ar', 'ur', 'roman-ur'];
const known = v => LANGS.includes(clean(v)) ? clean(v) : '';
// What to store as this patient's language, given what is on file.
const nextLang = stored => c.language
  || (c.script === 'ar' || c.script === 'ur' ? c.script : '')
  || (c.script === 'en' ? (stored === 'roman-ur' ? 'roman-ur' : 'en') : '')
  || stored;

/* ------------------------------------------------------------------- read */
if (c.mode === 'read') {
  const handoff = rows(2).some(r => mine(r[3]) &&
    (clean(r[2]).toUpperCase() !== 'DONE' || now - (Date.parse(clean(r[1])) || 0) < 24 * 3600000));
  return [{ json: { mode: 'read', hasUpdates: false, appends: [], response: {
    ok: true,
    history: history.map(m => ({ role: m.r === 'p' ? 'patient' : m.r === 'n' ? 'note' : 'assistant', text: m.t })),
    language: known(sess && sess.r[2]) || known(pat && pat.r[3]),
    patient: pat && clean(pat.r[1])
      ? { known: true, name: clean(pat.r[1]), email: clean(pat.r[2]), language: known(pat.r[3]), visits: Number(pat.r[6]) || 0 }
      : { known: false },
    handoff } } }];
}

/* ------------------------------------------------------------------- save */
const iso = new Date(now).toISOString();
const data = [], appends = [];

if (c.said || c.reply || c.note) {
  if (c.said)  history.push({ r: 'p', t: c.said });
  if (c.reply) history.push({ r: 'a', t: c.reply });
  if (c.note)  history.push({ r: 'n', t: c.note });
  history = history.slice(-c.HISTORY_MESSAGES);
  let json = JSON.stringify(history);
  while (json.length > 45000 && history.length > 2) { history.shift(); json = JSON.stringify(history); }   // a cell holds 50,000 characters
  const row = [c.phone, iso, nextLang(known(sess && sess.r[2])), json];
  if (sess) data.push({ range: `SessionState!A${sess.rowNumber}:D${sess.rowNumber}`, values: [row] });
  else appends.push({ tab: 'SessionState', range: 'SessionState!A:D', row });
}

if (pat) {
  const r = pat.r;
  data.push({ range: `Patients!A${pat.rowNumber}:G${pat.rowNumber}`, values: [[
    clean(r[0]) || c.phone,
    clean(r[1]) || c.profile.name,              // the name and email on file are kept: a later booking may be for a relative
    clean(r[2]) || c.profile.email,
    nextLang(known(r[3])),
    clean(r[4]) || iso, iso,
    (Number(r[6]) || 0) + (c.visit ? 1 : 0) ]] });
} else if (c.profile.name || c.profile.email || c.visit) {
  appends.push({ tab: 'Patients', range: 'Patients!A:G', row: [c.phone, c.profile.name, c.profile.email, nextLang(''), iso, iso, c.visit ? 1 : 0] });
}

return [{ json: { mode: 'save', SHEET_ID: c.SHEET_ID,
  hasUpdates: data.length > 0, updates: { valueInputOption: 'RAW', data }, appends,
  response: { ok: true, saved: data.length + appends.length } } }];

// A patient we have no row for yet: their row is appended (the sheet grows by itself).
const p = $('Plan').first().json;
return (p.appends || []).map(a => ({ json: { SHEET_ID: p.SHEET_ID, range: a.range, body: { values: [a.row] } } }));
